<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue'
import L from 'leaflet'
const emit=defineEmits(['close'])
const mapEl=ref(null),collection=ref({type:'FeatureCollection',features:[]}),revision=ref(0),baseline=ref(''),draft=ref([]),drawing=ref(false),selected=ref(''),name=ref(''),capacity=ref(100),error=ref(''),message=ref(''),busy=ref(false)
const dirty=computed(()=>JSON.stringify(collection.value)!==baseline.value||draft.value.length>0)
const chosen=computed(()=>collection.value.features.find(f=>f.properties.id===selected.value))
let map,layer,preview,observer
async function request(method='GET',body){const r=await fetch('/api/parking-editor',{method,headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:'保存失败');return d}
function paint(){if(!map)return;layer.clearLayers();L.geoJSON(collection.value,{style:f=>({color:f.properties.id===selected.value?'#1a73e8':'#188038',fillOpacity:.25,weight:3}),onEachFeature(f,l){const text=document.createElement('span');text.textContent=f.properties.name;l.bindTooltip(text,{permanent:true});l.on('click',e=>{if(drawing.value)return;L.DomEvent.stopPropagation(e);selected.value=f.properties.id;paint()})}}).addTo(layer);preview.clearLayers();if(draft.value.length)L.polyline(draft.value.map(p=>[p[1],p[0]]),{color:'#1a73e8',dashArray:'5 5'}).addTo(preview)}
function fit(){const b=layer.getBounds();if(b.isValid())map.fitBounds(b,{padding:[30,30],maxZoom:19})}
async function load(){if(baseline.value&&dirty.value&&!confirm('丢弃未保存修改并重新加载？'))return;try{const d=await request();collection.value=d.collection;revision.value=d.revision;baseline.value=JSON.stringify(d.collection);draft.value=[];selected.value='';paint();fit()}catch(e){error.value=e.message}}
function finish(){if(draft.value.length<3||!name.value.trim()){error.value='请填写名称，并在地图上点至少3个边界顶点';return}collection.value.features.push({type:'Feature',properties:{id:'parking_'+crypto.randomUUID().replaceAll('-','').slice(0,12),name:name.value.trim(),capacity:Number(capacity.value)},geometry:{type:'Polygon',coordinates:[[...draft.value,draft.value[0]]]}});draft.value=[];drawing.value=false;name.value='';error.value=''}
async function save(){if(draft.value.length){error.value='请先完成或取消正在绘制的边界';return}busy.value=true;error.value='';try{const d=await request('PUT',{revision:revision.value,collection:collection.value});collection.value=d.collection;revision.value=d.revision;baseline.value=JSON.stringify(d.collection);message.value='停车区已保存，版本 '+d.revision}catch(e){error.value=e.message}finally{busy.value=false}}
function exportJson(){const url=URL.createObjectURL(new Blob([JSON.stringify(collection.value,null,2)],{type:'application/geo+json'}));const a=document.createElement('a');a.href=url;a.download='campus-parking-areas.geojson';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function close(){if(!dirty.value||confirm('还有未保存修改，确认返回？'))emit('close')}
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue=''}}
watch(collection,paint,{deep:true});watch(draft,paint,{deep:true})
onMounted(async()=>{map=L.map(mapEl.value,{center:[34.37162,108.89754],zoom:17});L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);layer=L.featureGroup().addTo(map);preview=L.layerGroup().addTo(map);map.on('click',e=>{if(drawing.value)draft.value.push([Number(e.latlng.lng.toFixed(7)),Number(e.latlng.lat.toFixed(7))])});observer=new ResizeObserver(()=>map.invalidateSize());observer.observe(mapEl.value);window.addEventListener('beforeunload',beforeUnload);await load()})
onBeforeUnmount(()=>{window.removeEventListener('beforeunload',beforeUnload);observer?.disconnect();map?.remove()})
</script>
<template><Teleport to="body"><section class="parking-editor"><header><strong>地图停车区标注</strong><span>{{dirty?'有未保存修改':'已保存'}} · v{{revision}}</span><button @click="close">返回调试页</button></header><div class="body"><aside><p>沿真实可停车地面的边界逐点绘制。不要把建筑、花坛或通道圈进去。</p><label>新区域名称<input v-model="name" maxlength="100" placeholder="例如：鸿翔园1号公寓东侧"></label><label>参考容量<input v-model.number="capacity" type="number" min="1" max="100000"></label><button @click="drawing=!drawing">{{drawing?'暂停绘制':'开始画边界'}}</button><button :disabled="!draft.length" @click="draft.pop()">撤销一点</button><button :disabled="draft.length<3" @click="finish">完成区域</button><button @click="draft=[];drawing=false">取消草稿</button><p>{{drawing?'正在绘制：点击地图添加顶点':'点击已有区域可编辑名称和容量'}} · {{draft.length}} 个顶点</p><label>已有区域<select v-model="selected" @change="paint"><option value="">请选择</option><option v-for="f in collection.features" :key="f.properties.id" :value="f.properties.id">{{f.properties.name}}</option></select></label><div v-if="chosen"><p v-if="chosen.properties.geometry_validation==='legacy_boundary_needs_review'" class="error">该旧边界存在交叉或重复点，请核对后重画。</p><label>名称<input v-model="chosen.properties.name" maxlength="100"></label><label>容量<input v-model.number="chosen.properties.capacity" type="number" min="1" max="100000"></label><button @click="collection.features=collection.features.filter(f=>f.properties.id!==selected);selected=''">删除区域</button><p>需修改边界时，删除后重画；已关联道路入口的区域须先解除关联。</p></div><button class="primary" :disabled="busy||!dirty" @click="save">保存到数据库</button><button @click="exportJson">导出 GeoJSON 备份</button><button @click="load">重新加载</button><button @click="fit">查看全部区域</button><p role="status">{{message}}</p><p class="error" role="alert">{{error}}</p><p>这里标注的是地图经纬度范围；照片中的绿色区域需在照片标注工具中另画。</p></aside><div ref="mapEl" class="editor-map" aria-label="停车区绘制地图"></div></div></section></Teleport></template>
<style scoped>
.parking-editor{position:fixed;inset:0;z-index:2300;background:white;display:flex;flex-direction:column;color:#243047}.parking-editor header{display:flex;gap:20px;align-items:center;padding:16px;border-bottom:1px solid #ddd}.parking-editor header span{flex:1}.body{display:flex;flex:1;min-height:0}.body aside{width:320px;overflow:auto;padding:20px}.editor-map{flex:1;min-width:0}.parking-editor p{font-size:12px;color:#64748b;line-height:1.7;margin:12px 0}.parking-editor label{display:block;margin:12px 0}.parking-editor input,.parking-editor select{display:block;padding:9px;width:100%;border:1px solid #cbd5e1;border-radius:7px;margin-top:5px}.parking-editor button{padding:9px 12px;margin:4px 3px;border:1px solid #cbd5e1;border-radius:7px;background:white}.parking-editor .primary{background:#1a73e8;color:white;width:100%}.parking-editor .error{color:#b91c1c}@media(max-width:700px){.body{flex-direction:column-reverse}.body aside{width:100%;max-height:45%}.editor-map{min-height:40vh}}
</style>
